+shader_type canvas_item;
+// The Minotaur's body (MinotaurBoss), the traced art, his red cape rippling:
+// where the cape mask is set, each pixel is taken from a little way along a
+// wave travelling out through the cloth; the rest of him holds still.
+
+uniform sampler2D cape_mask;      // the cape, softened (same size as the texture)
+uniform vec2 tex_size;
+uniform float sway = 16.0;        // px at full mask
+uniform float time_offset = 0.0;
+
+varying vec4 tint;
+
+void vertex() {
+	tint = COLOR;
+}
+
+void fragment() {
+	vec2 p = UV * tex_size;
+	float t = TIME + time_offset;
+	float m = texture(cape_mask, UV).r;
+	vec2 off = vec2(sin(t * 2.1 + p.y * 0.022 + p.x * 0.006) + 0.4 * sin(t * 3.3 + p.x * 0.03),
+		cos(t * 1.7 + p.x * 0.018) * 0.8) * sway * m;
+	vec2 uv = (p - off) / tex_size;
+	COLOR = texture(TEXTURE, uv) * tint;
+	if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) {
+		COLOR.a = 0.0;
+	}
+}

@@ -1,0 +1,29 @@ 
+shader_type canvas_item;
+// Skylla's upper body (SeaWitch): the traced art, her hair drifting as if in
+// water - nothing moves below `still_y` (the crown, the face, the body), and
+// the curls sway more the higher they are, in slow overlapping waves.
+
+uniform vec2 tex_size;
+uniform float still_y = 250.0;    // texture px: no sway from here down
+uniform float top_y = 40.0;       // texture px: full sway from here up
+uniform float sway = 9.0;         // px at the top
+uniform float time_offset = 0.0;
+
+varying vec4 tint;   // (the vertex colour: modulate, hit flashes)
+
+void vertex() {
+	tint = COLOR;
+}
+
+void fragment() {
+	vec2 p = UV * tex_size;
+	float t = TIME + time_offset;
+	float k = smoothstep(still_y, top_y, p.y);
+	vec2 off = vec2(sin(t * 1.1 + p.y * 0.021 + p.x * 0.008) + 0.5 * sin(t * 1.7 + p.x * 0.019),
+		0.5 * sin(t * 0.9 + p.x * 0.015)) * sway * k;
+	vec2 uv = (p - off) / tex_size;
+	COLOR = texture(TEXTURE, uv) * tint;
+	if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) {
+		COLOR.a = 0.0;
+	}
+}

@@ -1,0 +1,37 @@ 
+shader_type canvas_item;
+// Skylla's tentacles (SeaWitch), the traced art itself made to writhe: each
+// pixel is taken from a little way along the tentacle it belongs to - more the
+// farther it is from the hub, so the roots hold and the tips sway most - with
+// a wave travelling out along every tentacle and a slow coil, each tentacle
+// (by its angle round the hub) out of step with the next.
+
+uniform vec2 tex_size;            // the texture's size in px
+uniform vec2 hub;                 // the tentacles' hub, in texture px
+uniform float sway = 26.0;        // px of sideways sway at the tips
+uniform float reach = 520.0;      // px from the hub to the tips
+uniform float speed = 1.0;
+uniform float time_offset = 0.0;
+
+varying vec4 tint;   // (the vertex colour: modulate, hit flashes)
+
+void vertex() {
+	tint = COLOR;
+}
+
+void fragment() {
+	vec2 p = UV * tex_size - hub;
+	float r = length(p);
+	float ang = atan(p.y, p.x);
+	float t = TIME * speed + time_offset;
+	float k = smoothstep(50.0, reach, r);               // 0 at the roots, 1 at the tips
+	vec2 radial = p / max(r, 1.0);
+	vec2 tang = vec2(-radial.y, radial.x);
+	float wave = sin(t * 1.5 - r * 0.016 + ang * 3.0) + 0.45 * sin(t * 0.9 - r * 0.009 + ang * 5.0);
+	float coil = sin(t * 0.7 + ang * 2.0);
+	vec2 off = tang * sway * k * k * wave + radial * sway * 0.35 * k * coil;
+	vec2 uv = (p - off + hub) / tex_size;
+	COLOR = texture(TEXTURE, uv) * tint;
+	if (uv.x < 0.0 || uv.y < 0.0 || uv.x > 1.0 || uv.y > 1.0) {
+		COLOR.a = 0.0;
+	}
+}
